import{_ as t,a}from"./chunks/results-browser.CdA7rjFC.js";import{_ as i}from"./chunks/preview-window.DO-cQqMu.js";import{_ as r,o,c as n,a2 as s}from"./chunks/framework.Cv-B11KK.js";const k=JSON.parse('{"title":"bbtex","description":"","frontmatter":{"title":"bbtex","sidebar":false,"prev":false,"next":false},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1790342103000}'),l={name:"index.md"};function d(c,e,p,h,b,u){return o(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="bbtex" tabindex="-1">bbtex <a class="header-anchor" href="#bbtex" aria-label="Permalink to &quot;bbtex&quot;">​</a></h1><p class="subtitle">LaTeX package for BBEdit</p><p class="meta"><strong>Version:</strong> v0.1.0 · <strong>Platform:</strong> macOS, Apple Silicon · <strong>License:</strong> MIT · <strong>Status:</strong> first release, totally vibe coded</p><p>I write my papers in BBEdit, and bbtex is the set of LaTeX tools I wanted there: press <kbd>⌘</kbd><kbd>K</kbd> to build, click an error to land on its line, jump between the source and the PDF in Skim, and check an equation without recompiling the whole paper. It lives in BBEdit&#39;s <strong>Scripts</strong> menu and uses BBEdit&#39;s own results browser and preview windows, so it should feel like part of the editor.</p><p>New here? Start with <a href="./getting-started">Getting started</a>.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><ul><li><strong>Builds.</strong> <kbd>⌘</kbd><kbd>K</kbd> saves the project, runs latexmk (pdfLaTeX, XeLaTeX, LuaLaTeX) or Tectonic, and lists errors and warnings in the results browser. See <a href="./project-builds">compiling projects</a>.</li><li><strong>SyncTeX with Skim.</strong> The PDF follows the cursor without stealing focus; ⌘-click in Skim goes back to the source.</li><li><strong>Equation previews.</strong> Selected math renders with the document&#39;s own preamble in a small window, on demand, on save, or following the selection. See <a href="./selection-preview">equation previews</a>.</li><li><strong>Project outline.</strong> Search sections, equations, captions and labels across included files and jump there. See <a href="./project-navigation">project outline</a>.</li><li><strong>Citations and references.</strong> Pick keys by author, title, year or label context. See <a href="./citation-reference-pickers">the pickers</a>.</li><li><strong>Environment editing.</strong> Change, toggle or wrap environments in one undo; TexLab supplies completion. See <a href="./bbedit-editing">writing and editing</a>.</li></ul><h2 id="a-quick-tour" tabindex="-1">A quick tour <a class="header-anchor" href="#a-quick-tour" aria-label="Permalink to &quot;A quick tour&quot;">​</a></h2><p>Press <kbd>⌘</kbd><kbd>K</kbd> and Skim opens the PDF where the cursor is:</p><p><img src="'+t+'" alt="A compiled paper in Skim"></p><p>A broken build lists its errors in BBEdit, one click from the line:</p><p><img src="'+a+'" alt="LaTeX Results listing an undefined control sequence in model.tex, line 7"></p><p>Select an equation to see it rendered with the document&#39;s preamble:</p><p><img src="'+i+'" alt="The preview window showing a rendered display equation"></p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p>Download <code>bbtex-macos-arm64.bbpackage.zip</code> from the <a href="https://github.com/LouLouLibs/bbtex/releases" target="_blank" rel="noreferrer">releases page</a>, unzip it, double-click <code>bbtex.bbpackage</code>, and run <strong>Scripts → LaTeX — Doctor</strong>. You need MacTeX (or TinyTeX) and Skim; <a href="./getting-started">Getting started</a> covers the rest, including a source install.</p><h2 id="totally-vibe-coded" tabindex="-1">Totally vibe coded <a class="header-anchor" href="#totally-vibe-coded" aria-label="Permalink to &quot;Totally vibe coded&quot;">​</a></h2><p>Every line of bbtex, its tests and these pages was written by an AI coding agent (<a href="https://claude.com/claude-code" target="_blank" rel="noreferrer">Claude Code</a>), with me describing what I wanted and trying it in BBEdit. It is tested fairly hard (unit, cram, real-engine and native BBEdit checks), but keep your papers in version control and <a href="https://github.com/LouLouLibs/bbtex/issues" target="_blank" rel="noreferrer">open an issue</a> when something looks off. <a href="./about">About bbtex</a> has the longer story.</p>',18)])])}const w=r(l,[["render",d]]);export{k as __pageData,w as default};
